import{_ as o,C as r,o as d,c as s,a2 as a,E as n}from"./chunks/framework.BetZR81g.js";const P=JSON.parse('{"title":"HChat 的分层：两条链路、两台聊天服与一次跨服消息","description":"从 HTTP 登录到 TCP 长连接聊天，再到两台 ChatServer 之间的 gRPC 转发，拆开一个分布式 IM 的请求路径。","frontmatter":{"title":"HChat 的分层：两条链路、两台聊天服与一次跨服消息","titleHtml":"HChat 的分层：两条<span class=\\"nowrap\\">链路</span>、两台<span class=\\"nowrap\\">聊天服</span>与<span class=\\"nowrap\\">一次跨服消息</span>","date":"2026-10-26","category":"分布式系统","tags":["分布式","gRPC","C++"],"description":"从 HTTP 登录到 TCP 长连接聊天，再到两台 ChatServer 之间的 gRPC 转发，拆开一个分布式 IM 的请求路径。","read":8,"order":2},"headers":[],"relativePath":"blog/posts/hchat-architecture.md","filePath":"blog/posts/hchat-architecture.md"}'),c={name:"blog/posts/hchat-architecture.md"};function l(p,t,i,h,u,C){const e=r("ArticleMeta");return d(),s("div",null,[t[0]||(t[0]=a('<h1 id="hchat-的分层-两条链路、两台聊天服与一次跨服消息" tabindex="-1">HChat 的分层：两条<span class="nowrap">链路</span>、两台<span class="nowrap">聊天服</span>与<span class="nowrap">一次跨服消息</span> <a class="header-anchor" href="#hchat-的分层-两条链路、两台聊天服与一次跨服消息" aria-label="Permalink to &quot;HChat 的分层：两条&lt;span class=&quot;nowrap&quot;&gt;链路&lt;/span&gt;、两台&lt;span class=&quot;nowrap&quot;&gt;聊天服&lt;/span&gt;与&lt;span class=&quot;nowrap&quot;&gt;一次跨服消息&lt;/span&gt;&quot;">​</a></h1>',1)),n(e),t[1]||(t[1]=a(`<p>HChat 是一个学习性质的分布式即时通讯项目：Qt 客户端、Boost.Beast HTTP 网关、gRPC 状态与转发服务、两台 Asio TCP 聊天服，外加 Redis 和 MySQL。功能不少，但真正值得拆的是它的分层方式。</p><blockquote><p>README 里写明了：这是一个基于 llfcchat 教程实现的学习项目。下面的分层说明来自项目自己的文档和目录结构。</p></blockquote><h2 id="两条链路-互不影响" tabindex="-1">两条链路，互不影响 <a class="header-anchor" href="#两条链路-互不影响" aria-label="Permalink to &quot;两条链路，互不影响&quot;">​</a></h2><p>客户端没有把所有请求塞进同一条连接，而是分成两条独立链路：</p><ul><li><strong>HTTP 到 GateServer</strong>：注册、登录、重置密码、上传和下载头像。</li><li><strong>TCP 到 ChatServer</strong>：登录后的实时聊天。</li></ul><p>登录流程把两条链路串起来：先通过 HTTP 拿到账号信息，再用 token 建立 TCP 连接登录 ChatServer；登录回包里直接带回好友列表。这样账号类操作走请求-响应，聊天类操作走长连接，互不阻塞。</p><h2 id="服务与端口" tabindex="-1">服务与端口 <a class="header-anchor" href="#服务与端口" aria-label="Permalink to &quot;服务与端口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>服务</th><th>类型</th><th>端口</th><th>职责</th></tr></thead><tbody><tr><td>GateServer</td><td>HTTP</td><td>8080</td><td>登录、注册、重置、上传、头像下载</td></tr><tr><td>StatusServer</td><td>gRPC</td><td>50052</td><td>在线状态、心跳</td></tr><tr><td>ChatServer 1</td><td>TCP / RPC</td><td>8990 / 50055</td><td>聊天主节点</td></tr><tr><td>ChatServer 2</td><td>TCP / RPC</td><td>8991 / 50056</td><td>聊天从节点</td></tr><tr><td>VarifyServer</td><td>gRPC</td><td>50051</td><td>Node.js 邮件验证码</td></tr><tr><td>MySQL</td><td>—</td><td>3308</td><td>业务库 Hcat</td></tr><tr><td>Redis</td><td>—</td><td>6380</td><td>验证码、token、在线状态</td></tr></tbody></table><p>端口都从各服务的 <code>config.ini</code> 读取；改端口时要同步启动脚本和测试脚本，这也是分布式项目里很容易漏的一步。</p><h2 id="为什么聊天不用-http" tabindex="-1">为什么聊天不用 HTTP <a class="header-anchor" href="#为什么聊天不用-http" aria-label="Permalink to &quot;为什么聊天不用 HTTP&quot;">​</a></h2><p>聊天需要服务端主动推送，HTTP 的请求-响应模型不适合长期占用。ChatServer 用 Boost.Asio 维护 TCP 长连接，消息帧是自定义格式：<strong>2 字节 id + 2 字节长度（大端）+ 消息体</strong>。固定头部让服务端可以先读长度、再读内容，避免粘包和半包问题。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>+--------+----------+------------------+</span></span>
<span class="line"><span>| 2 字节 | 2 字节   | 消息体           |</span></span>
<span class="line"><span>| id     | 长度     | ...              |</span></span>
<span class="line"><span>+--------+----------+------------------+</span></span></code></pre></div><p>协议层还有心跳、断线重连、异地登录踢人、断点续传和大文件流式上传。它们的共同点是都需要“连接状态”，这也是 TCP 链路存在的理由。</p><h2 id="跨服消息" tabindex="-1">跨服消息 <a class="header-anchor" href="#跨服消息" aria-label="Permalink to &quot;跨服消息&quot;">​</a></h2><p>两台 ChatServer 共享同一个 Redis。在线状态由 StatusServer 统一维护，Redis 里存验证码、token、在线状态和分布式协调信息。</p><p>当两个用户分别连在不同节点上时，消息不能只在本节点投递：发送方所在的 ChatServer 会通过节点间的 gRPC 连接（50055 / 50056）把消息转给另一台，再由对方投递给目标用户。这样横向加节点时，不需要让所有客户端重连到同一台机器。</p><blockquote><p>把“用户在哪台机器上”这件事交给 Redis 和 StatusServer，聊天服本身就能保持相对无状态，扩容和重启都更容易。</p></blockquote><h2 id="数据放在哪" tabindex="-1">数据放在哪 <a class="header-anchor" href="#数据放在哪" aria-label="Permalink to &quot;数据放在哪&quot;">​</a></h2><p>持久化数据在 MySQL：用户、好友关系、好友申请、会话、私聊映射和聊天消息都有独立的表。Redis 负责短生命周期的状态：验证码、token、在线状态。这个划分让短生命周期的状态不必写进业务库，减少高频写压力。</p><h2 id="几个真实的工程坑" tabindex="-1">几个真实的工程坑 <a class="header-anchor" href="#几个真实的工程坑" aria-label="Permalink to &quot;几个真实的工程坑&quot;">​</a></h2><p>这个项目里踩过、也写进 README 的几个问题，比架构图更有意思：</p><ul><li><strong>MySQL Connector/C++ 与 Debug 运行时</strong>：Connector 只提供 Release DLL（<code>/MD</code>），原生 Debug（<code>/MDd</code>）在跨 DLL 传 <code>sql::SQLString</code> 时会因 STL 布局不同而崩溃。解决方式是把 <code>Debug|x64</code> 改成 Release 运行时（<code>/MD</code> + <code>NDEBUG</code> + <code>_ITERATOR_DEBUG_LEVEL=0</code>）但保留无优化，这样既能连 MySQL 又能断点。</li><li><strong>GateServer 的工作目录</strong>：它从当前工作目录读取 <code>config.ini</code>，所以必须从 <code>GateServer/</code> 目录启动；exe 同级还要有 MySQL 认证插件目录 <code>plugin/</code>，否则会出现 <code>mysql_native_password</code> 加载失败。</li><li><strong>客户端构建环境</strong>：<code>.pro</code> 的 post-link 用了 cmd 语法（<code>copy /Y</code>、<code>xcopy</code>），在 Git Bash 里跑 qmake/make 会把 <code>/Y</code> 当成 POSIX 路径，必须用 Qt Creator 构建。</li></ul><p>这些问题不影响架构，但会让第一次跑起来的人卡很久。把它们写进 README，比事后解释省事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>HChat 的分层可以概括成：HTTP 管账号，TCP 管聊天，Redis 管共享状态，gRPC 管跨节点，MySQL 管持久化。每一层只做一件事，组合起来才是一个能横向扩展的 IM。</p><p>源码在 <a href="https://github.com/Stan-Vincent/HChat-demo" target="_blank" rel="noreferrer">GitHub</a>。README 里有完整的启动脚本、端口表和测试脚本。</p>`,26))])}const T=o(c,[["render",l]]);export{P as __pageData,T as default};
